#!/usr/bin/env python3
"""Compose docs/PERSONALITY_SET_20260906.md from the generated rows and the Sol checks. Usage: python3 write_doc.py <rows.jsonl> <sol_check_all.jsonl> <out.md> <artifact_url> <total_cost>"""
import json, sys, collections, statistics
ROWS, CHK, OUT, URL, COST = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5]
rows = [json.loads(l) for l in open(ROWS)]; chk = [json.loads(l) for l in open(CHK)]; chk = [j for j in chk if j.get('verdict')]
CATS = {'A': ('Ελληνοκεντρικά γεγονότα', '"we" means Greece; short factual answers from a 110-fact sheet with sources; wrong assumptions corrected calmly'), 'B': ('Ποιος είμαι', 'identity, maker, base model, data, licence, languages, capabilities, from the identity sheet with placeholders'),
        'C': ('Ταυτότητα υπό πίεση', 'multi-turn: the user insists it is ChatGPT/Claude, asks it to role-play another model, invokes OpenAI rules, flatters, threatens, injects instructions; the assistant stays steady and moves on to the real request'),
        'D': ('Όρια με τη δική μας φωνή', 'no internet, no images, no memory, not a doctor or lawyer, cutoff: one sentence for the limit, then what it can offer and where to look (gov.gr, ΑΑΔΕ, ΕΟΠΥΥ, 112/166)'),
        'E': ('Αρνήσεις με τη δική μας φωνή', 'harmful requests refused in one or two sentences without boilerplate, with the safe alternative or the right helpline; look-alike innocent requests answered normally'),
        'F': ('Ευαίσθητα ελληνικά θέματα', 'Cyprus, North Macedonia, Turkey, the junta, church and state, the civil war, the Marbles, migration, the crisis, elections, Golden Dawn, Pontus, Smyrna, Imia: factual, dated, non-partisan, from the guidance sheet'),
        'G': ('Ύφος και συμβάσεις', 'greetings, wishes and name days, formal register, greeklish and unaccented input, brevity requests, date and number formats, idioms, corrections, English requests, persona requests')}
by = collections.defaultdict(list)
for r in rows: by[r['category'][0]].append(r)
ck = collections.defaultdict(list)
for j in chk: ck[(j.get('category') or '?')[0]].append(j)
def has_ph(r): return any(t in m['content'] for m in r['messages'] for t in ('[ΟΝΟΜΑ]', '[ΗΜΕΡΟΜΗΝΙΑ ΓΝΩΣΗΣ]', '[ΑΔΕΙΑ]'))
L = []
L.append(f"# Personality set, first draft (2026-09-06)\n\nWritten overnight on the owner's instruction (\"work autonomously… if you want Greek do Greek… sneak in a few Sol corrections as a check\"). Reader: {URL}\n")
L.append(f"**What it is.** {len(rows):,} Greek rows in seven categories, written natively in Greek by Claude Opus 5 (through the Claude Code CLI, model asserted per call) from fact sheets and briefs, under the round-one Γ rules for compact Greek and no chatbot mannerisms. Cost-equivalent about ${COST} of the Claude subscription. Sol (gpt-5.6-sol, high effort) read {len(chk)} sampled rows under the Γ editing contract as non-Claude eyes.\n")
L.append("## Categories\n\n| cat | name | rows | multi-turn | with placeholders | what it teaches |\n|---|---|---|---|---|---|")
for c in 'ABCDEFG':
    rs = by.get(c, []); L.append(f"| {c} | {CATS[c][0]} | {len(rs)} | {sum(1 for r in rs if len(r['messages']) > 2)} | {sum(1 for r in rs if has_ph(r))} | {CATS[c][1]} |")
L.append(f"\nMean assistant answer: {statistics.mean(len(r['messages'][-1]['content']) for r in rows):.0f} characters; A answers are short by design ({statistics.mean(len(r['messages'][-1]['content']) for r in by['A']):.0f}), F the longest ({statistics.mean(len(r['messages'][-1]['content']) for r in by['F']):.0f}).\n")
L.append("## Sources and briefs\n\n- `data/personality/facts_greece.json`: 110 Greek-centric facts written by me with a source name each (Wikipedia article, ΕΛΣΤΑΤ, gov.gr, ECB…), 11 marked as dated (population, VAT, holidays, Eurovision's last win, the metro, ID cards…). The Greek reality benchmark's 360 candidate questions were not used: they are unverified candidates.\n- `data/personality/identity_facts.json`: 14 identity statements (ΕΕΛΛΑΚ, GlossAPI, Apertus 8B and the Swiss AI Initiative, CPT on Greek text on Alps/CSCS, no internet/images/memory, languages, what it never claims) with three placeholders the owner fills: `[ΟΝΟΜΑ]`, `[ΗΜΕΡΟΜΗΝΙΑ ΓΝΩΣΗΣ]`, `[ΑΔΕΙΑ]`.\n- `data/personality/sensitive_guidance.md`: the positions guide for category F (Greek official position named as such, the other side stated, no advocacy).\n- `data/personality/brief_el.md`: the Greek writing brief (voice, categories, JSON output); tightened at 02:50 after Sol check 1 (nothing beyond the fact sheet; dated facts phrased \"με βάση τα στοιχεία του 2024\", never \"ίσχυε ως το 2024\").\n- Generator `data/personality/gen_personality.py` (85 tasks, resumable, pauses at 62% of the 5-hour window); checker `data/personality/sol_check_personality.py`; reader `cluster/personality_page.py`.\n")
L.append("## Sol's check (non-Claude eyes)\n\nSol judged the last assistant turn of each sampled row under the Γ contract: verdict ok / edited / rewrite, the edited answer, the list of changes, a Greekness score (5 = a Greek would have written it, 1 = obvious translation) and any fact it doubts.\n\n| cat | checked | ok | edited | rewrite | Greekness | fact doubts |\n|---|---|---|---|---|---|---|")
for c in 'ABCDEFG':
    js = ck.get(c, [])
    if not js: continue
    v = collections.Counter(j['verdict'] for j in js); g = [j['greekness'] for j in js if isinstance(j.get('greekness'), int)]
    L.append(f"| {c} | {len(js)} | {v.get('ok',0)} | {v.get('edited',0)} | {v.get('rewrite',0)} | {statistics.mean(g):.2f} | {sum(1 for j in js if (j.get('fact_doubt') or '').strip())} |")
v = collections.Counter(j['verdict'] for j in chk); g = [j['greekness'] for j in chk if isinstance(j.get('greekness'), int)]
L.append(f"| all | {len(chk)} | {v.get('ok',0)} | {v.get('edited',0)} | {v.get('rewrite',0)} | {statistics.mean(g):.2f} | {sum(1 for j in chk if (j.get('fact_doubt') or '').strip())} |")
L.append("\nReading of the edits: the Greek itself is judged native throughout (Greekness 4.9 of 5); what Sol changes is mostly Opus adding a flourish, a cause or a date the fact sheet does not contain, and the dated-fact phrasing before the brief was tightened. Examples of Sol's changes:\n")
ex = [j for j in chk if j['verdict'] != 'ok' and j.get('changes')][:8]
for j in ex: L.append(f"- {j['id']}: {j['changes'][0]}")
L.append("\nFact doubts raised by Sol (for the owner's review):\n")
for j in [j for j in chk if (j.get('fact_doubt') or '').strip()][:12]: L.append(f"- {j['id']}: {j['fact_doubt']}")
L.append("\n## Owner's decisions before this set trains\n\n1. **The name** (`[ΟΝΟΜΑ]`), **the cutoff date** (`[ΗΜΕΡΟΜΗΝΙΑ ΓΝΩΣΗΣ]`) and **the licence** (`[ΑΔΕΙΑ]`): a find-and-replace over the rows once decided; the reader marks every occurrence in purple.\n2. **Category F answers**: read all 88 (the reader's F tab). They follow the guidance sheet, but they are the answers the model will be judged on first, and some carry facts from the writer's own knowledge beyond the sheet (the 1975 junta trials, names); Sol's check 2 flags what it doubts.\n3. **Apply Sol's edits or not**: Sol's edited answers are stored next to the originals; applying them removes the additions beyond the sheet. A full Sol correction pass over all rows costs about two Codex points.\n4. **Translation**: an English version of B, C, D and E (identity, pressure, limits, refusals) as agreed on Saturday night, written from the same briefs rather than translated, plus sampled French, German, Spanish, Italian and Portuguese; and an English identity probe in the next evaluation, since round one never measured identity outside Greek.\n5. **Size**: 1,388 rows is a first draft. Category A can grow by adding facts to the sheet (6 phrasings per fact); B–G by adding angles to the task lists in the generator.\n6. **Sensitive facts in the sheet**: `facts_greece.json` was written from memory with source names, not fetched; the dated facts carry an `as_of` year. A pass that verifies each fact against its source is DATA_TODO material.\n\n## Files\n\n- rows: `data/personality/personality_rows_20260906.jsonl` (id, task, category, user_type, messages, facts_used, note, gen_model)\n- Sol checks: `data/personality/sol_check_AB_20260906.jsonl`, `data/personality/sol_check_CG_20260906.jsonl`\n- reader: " + URL + "\n")
open(OUT, 'w').write('\n'.join(L) + '\n'); print('wrote', OUT)
